def prime_generator():
    n = 2
    while True:
        is_prime = True
        if n < 2:
            is_prime = False
        elif n == 2:
            is_prime = True
        elif n % 2 == 0:
            is_prime = False
        else:
            limit = int(math.isqrt(n))
            for d in range(3, limit + 1, 2):
                if n % d == 0:
                    is_prime = False
                    break

        if is_prime:
            yield n

        n += 1
