def prime_worker():
    # burn CPU by continuously checking successive integers for primality
    n = 2
    while True:
        if n == 2:
            pass
        elif n % 2 == 0:
            n += 1
            continue
        else:
            limit = int(math.isqrt(n))
            for d in range(3, limit + 1, 2):
                if n % d == 0:
                    break
        n += 1

if __name__ == "__main__":
    procs = []
    for _ in range(multiprocessing.cpu_count()):
        p = multiprocessing.Process(target=prime_worker)
        p.daemon = True
        p.start()
        procs.append(p)

    for p in procs:
        p.join()
